import React, { useState, useEffect } from 'react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import api from '../api';

function GroupResumeView({ resumeId, onClose, canEdit }) {
  const [resume, setResume] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showEditForm, setShowEditForm] = useState(false);

  useEffect(() => {
    loadResume();
  }, [resumeId]);

  const loadResume = async () => {
    try {
      setLoading(true);
      const data = await api.getGroupResume(resumeId);
      setResume(data);
    } catch (error) {
      console.error('Error loading resume:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = () => {
    // Close this view and signal parent to open edit form
    onClose();
    window.location.href = `#edit-${resumeId}`;
  };

  const generatePDF = () => {
    const doc = new jsPDF('portrait');
    const pageWidth = doc.internal.pageSize.getWidth();
    let yPos = 15;

    // Title with yellow highlight
    doc.setFillColor(255, 255, 0);
    doc.rect(55, yPos - 5, 100, 10, 'F');
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');
    doc.text('POP-UP Resume', pageWidth / 2, yPos, { align: 'center' });
    yPos += 10;

    // Hotel name
    doc.setFontSize(12);
    doc.setFont('helvetica', 'normal');
    doc.text('Nashville Marriott at Vanderbilt University', pageWidth / 2, yPos, { align: 'center' });
    yPos += 5;

    // GROUP COVER SHEET header (dark background)
    doc.setFillColor(64, 64, 64);
    doc.rect(14, yPos, pageWidth - 28, 7, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    doc.text('GROUP COVER SHEET', pageWidth / 2, yPos + 5, { align: 'center' });
    yPos += 12;
    doc.setTextColor(0, 0, 0);

    // Logo (if exists)
    if (resume.logo_filename) {
      try {
        const logoUrl = `/uploads/group-logos/${resume.logo_filename}`;
        doc.addImage(logoUrl, 'PNG', pageWidth / 2 - 25, yPos, 50, 25);
        yPos += 30;
      } catch (error) {
        console.error('Error adding logo:', error);
        yPos += 5;
      }
    } else {
      yPos += 5;
    }

    // Main info section (two columns)
    doc.setFontSize(9);
    doc.setFont('helvetica', 'bold');

    const leftCol = 14;
    const rightCol = pageWidth / 2 + 5;
    const lineHeight = 5;

    // Left column
    doc.text('Organization:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.organization || '', leftCol + 30, yPos);

    doc.setFont('helvetica', 'bold');
    doc.text('Post As:', leftCol, yPos + lineHeight);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.post_as || '', leftCol + 30, yPos + lineHeight);

    doc.setFont('helvetica', 'bold');
    doc.text('Arrival Date:', leftCol, yPos + lineHeight * 2);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.arrival_date || '', leftCol + 30, yPos + lineHeight * 2);

    // Right column
    doc.setFont('helvetica', 'bold');
    doc.text('Quote #:', rightCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.quote_number || '', rightCol + 20, yPos);

    doc.setFont('helvetica', 'bold');
    doc.text('Departure Date:', rightCol, yPos + lineHeight * 2);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.departure_date || '', rightCol + 30, yPos + lineHeight * 2);

    yPos += lineHeight * 3 + 3;

    // Separator line
    doc.setDrawColor(0, 0, 0);
    doc.line(14, yPos, pageWidth - 14, yPos);
    yPos += 5;

    // Contact details - two columns
    doc.setFont('helvetica', 'bold');
    doc.text('Master Account #:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.master_account || '', leftCol + 35, yPos);

    doc.setFont('helvetica', 'bold');
    doc.text('Market Code:', rightCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.market_code || '', rightCol + 25, yPos);
    yPos += lineHeight;

    doc.setFont('helvetica', 'bold');
    doc.text('Group Contact:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.group_contact || '', leftCol + 35, yPos);

    doc.setFont('helvetica', 'bold');
    doc.text('Telephone:', rightCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.telephone || '', rightCol + 25, yPos);
    yPos += lineHeight;

    doc.setFont('helvetica', 'bold');
    doc.text('In-House Contact:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.in_house_contact || '', leftCol + 35, yPos);

    doc.setFont('helvetica', 'bold');
    doc.text('Email:', rightCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.email || '', rightCol + 25, yPos);
    yPos += lineHeight;

    doc.setFont('helvetica', 'bold');
    doc.text('Sales Manager(s):', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.sales_manager || '', leftCol + 35, yPos);

    doc.setFont('helvetica', 'bold');
    doc.text('Event Manager(s):', rightCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.event_manager || '', rightCol + 30, yPos);
    yPos += lineHeight;

    doc.setFont('helvetica', 'bold');
    doc.text('Reservation Coordinator:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.reservation_coordinator || '', leftCol + 45, yPos);

    doc.setFont('helvetica', 'bold');
    doc.text('General Accountant:', rightCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.general_accountant || '', rightCol + 35, yPos);
    yPos += lineHeight + 3;

    // Gold Keys
    if (resume.gold_keys) {
      doc.setFont('helvetica', 'bold');
      doc.text('Gold Keys:', leftCol, yPos);
      doc.setFont('helvetica', 'normal');
      const goldKeysLines = resume.gold_keys.split('\n');
      goldKeysLines.forEach((line, i) => {
        doc.text(line, leftCol + 20, yPos + (i * 4));
      });
      yPos += (goldKeysLines.length * 4) + 3;
    }

    // Peak Attendees
    doc.setFont('helvetica', 'bold');
    doc.text('Peak Attendees:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.peak_attendees || '', leftCol + 30, yPos);
    yPos += lineHeight + 3;

    // Group Profile
    if (resume.group_profile) {
      doc.setFont('helvetica', 'bold');
      doc.text('Group Profile:', leftCol, yPos);
      yPos += lineHeight;
      doc.setFont('helvetica', 'normal');
      const profileLines = doc.splitTextToSize(resume.group_profile, pageWidth - 30);
      profileLines.forEach(line => {
        doc.text(line, leftCol, yPos);
        yPos += 4;
      });
      yPos += 3;
    }

    // GROUP ROOM BLOCK table
    const roomBlockRows = resume.room_block_rows ? JSON.parse(resume.room_block_rows) : [];
    if (roomBlockRows.length > 0) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.text('GROUP ROOM BLOCK:', leftCol, yPos);
      yPos += 5;

      autoTable(doc, {
        startY: yPos,
        head: [['Date', 'Day', 'Room Block', 'Contracted', 'Projected', 'Picked Up']],
        body: roomBlockRows.map(row => [row.date, row.day, row.roomBlock, row.contracted, row.projected, row.pickedUp]),
        styles: { fontSize: 8, cellPadding: 2 },
        headStyles: { fillColor: [200, 200, 200], textColor: [0, 0, 0] },
        theme: 'grid'
      });
      yPos = doc.lastAutoTable.finalY + 5;
    }

    // Check if we need page 2
    if (yPos > 220) {
      doc.addPage();
      yPos = 15;
    }

    // RESERVATION METHOD table
    const reservationMethodRows = resume.reservation_method_rows ? JSON.parse(resume.reservation_method_rows) : [];
    if (reservationMethodRows.length > 0) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.text('RESERVATION METHOD(S)', leftCol, yPos);
      yPos += 5;

      autoTable(doc, {
        startY: yPos,
        head: [['Room Block', 'Billing Method', 'Reservation Method', 'Reservation Type', 'Pre-Registration', 'Pre-Key']],
        body: reservationMethodRows.map(row => [row.roomBlock, row.billingMethod, row.reservationMethod, row.reservationType, row.preRegistration, row.preKey]),
        styles: { fontSize: 8, cellPadding: 2 },
        headStyles: { fillColor: [200, 200, 200], textColor: [0, 0, 0] },
        theme: 'grid'
      });
      yPos = doc.lastAutoTable.finalY + 5;
    }

    // RATES table
    const ratesRows = resume.rates_rows ? JSON.parse(resume.rates_rows) : [];
    if (ratesRows.length > 0) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.text('RATES:', leftCol, yPos);
      yPos += 5;

      autoTable(doc, {
        startY: yPos,
        head: [['Room Block', 'Start Date', 'End Date', 'Room Type', 'Room Occupancy', 'Negotiated Rate']],
        body: ratesRows.map(row => [row.roomBlock, row.startDate, row.endDate, row.roomType, row.roomOccupancy, row.negotiatedRate]),
        styles: { fontSize: 8, cellPadding: 2 },
        headStyles: { fillColor: [200, 200, 200], textColor: [0, 0, 0] },
        theme: 'grid'
      });
      yPos = doc.lastAutoTable.finalY + 10;
    }

    // PAGE 2 - BILLING INSTRUCTIONS & DEPARTMENTS
    if (yPos > 200) {
      doc.addPage();
      yPos = 15;
    }

    // BILLING INSTRUCTIONS
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.text('BILLING INSTRUCTIONS:', leftCol, yPos);
    yPos += 5;

    doc.setFontSize(9);
    doc.text('Payment Method:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.payment_method || '', leftCol + 35, yPos);

    doc.setFont('helvetica', 'bold');
    doc.text('Direct Bill Approved:', leftCol + 80, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.direct_bill_approved || '', leftCol + 120, yPos);
    yPos += lineHeight;

    doc.setFont('helvetica', 'bold');
    doc.text('Master Account:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.master_account_billing || '', leftCol + 35, yPos);
    yPos += lineHeight;

    doc.setFont('helvetica', 'bold');
    doc.text('Authorized Signers:', leftCol, yPos);
    doc.setFont('helvetica', 'normal');
    doc.text(resume.authorized_signers || '', leftCol + 35, yPos);
    yPos += lineHeight;

    if (resume.billing_address) {
      doc.setFont('helvetica', 'bold');
      doc.text('Billing Address:', leftCol, yPos);
      yPos += lineHeight;
      doc.setFont('helvetica', 'normal');
      const addressLines = resume.billing_address.split('\n');
      addressLines.forEach(line => {
        doc.text(line, leftCol + 5, yPos);
        yPos += 4;
      });
    }

    yPos += 5;

    // Department sections
    const departments = [
      { label: 'FRONTDESK', field: 'frontdesk' },
      { label: 'BELLSTAND', field: 'bellstand' },
      { label: 'CONCIERGE', field: 'concierge' },
      { label: 'GARAGE/VALET', field: 'garage_valet' },
      { label: 'OUTLET INFORMATION', field: 'outlet_information' },
      { label: 'HOUSEKEEPING', field: 'housekeeping' },
      { label: 'CATERING/BANQUETS', field: 'catering_banquets' },
      { label: 'AUDIO VISUAL', field: 'audio_visual' },
      { label: 'SHIPPING & RECEIVING', field: 'shipping_receiving' },
      { label: 'ACCOUNTING', field: 'accounting' }
    ];

    departments.forEach(dept => {
      if (resume[dept.field]) {
        if (yPos > 250) {
          doc.addPage();
          yPos = 15;
        }

        doc.setFont('helvetica', 'bold');
        doc.setFontSize(9);
        doc.text(dept.label + ':', leftCol, yPos);
        yPos += 4;

        doc.setFont('helvetica', 'normal');
        doc.setFontSize(8);
        const deptLines = resume[dept.field].split('\n');
        deptLines.forEach(line => {
          if (yPos > 280) {
            doc.addPage();
            yPos = 15;
          }
          doc.text(line, leftCol + 2, yPos);
          yPos += 3.5;
        });
        yPos += 3;
      }
    });

    // PAGE 3 - GROUP CONFIRMATION LIST
    const guestList = resume.guest_list ? JSON.parse(resume.guest_list) : [];
    if (guestList.length > 0 && guestList.some(g => g.firstName || g.lastName)) {
      doc.addPage();
      yPos = 15;

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(12);
      doc.text('Group Confirmation List', leftCol, yPos);
      yPos += 5;

      doc.setFontSize(10);
      doc.text('NASH/VANDERBILT UNIV', leftCol, yPos);
      yPos += 5;

      doc.setFontSize(9);
      doc.text(`Group: ${resume.organization?.toUpperCase() || 'GROUP'}`, leftCol, yPos);
      yPos += 7;

      autoTable(doc, {
        startY: yPos,
        head: [['Title', 'First Name', 'Last Name', 'Email', 'Arrival Date', 'Departure Date', 'Confirmation Number']],
        body: guestList.map(guest => [
          guest.title, guest.firstName, guest.lastName, guest.email, 
          guest.arrivalDate, guest.departureDate, guest.confirmationNumber
        ]),
        styles: { fontSize: 7, cellPadding: 2 },
        headStyles: { fillColor: [200, 200, 200], textColor: [0, 0, 0] },
        theme: 'grid'
      });
    }

    return doc;
  };

  const handleDownload = () => {
    const doc = generatePDF();
    const filename = `Group_Resume_${resume.organization?.replace(/\s+/g, '_')}_${resume.arrival_date}.pdf`;
    doc.save(filename);
  };

  if (loading) {
    return <div className="loading">Loading resume...</div>;
  }

  if (!resume) {
    return <div>Resume not found</div>;
  }

  return (
    <div className="main-content">
      <div className="page-header">
        <div>
          <h1>{resume.organization || 'Group Resume'}</h1>
          <p>{resume.arrival_date} - {resume.departure_date}</p>
        </div>
        <button className="btn btn-secondary" onClick={onClose}>
          ← Back to List
        </button>
      </div>

      <div style={{ marginBottom: '20px', display: 'flex', gap: '10px' }}>
        <button className="btn btn-success" onClick={handleDownload}>
          📄 Download PDF
        </button>
        {canEdit && (
          <button className="btn btn-primary" onClick={handleEdit}>
            ✏️ Edit Group
          </button>
        )}
      </div>

      {/* Display resume preview */}
      <div className="task-section" style={{ backgroundColor: '#f9f9f9', padding: '30px' }}>
        <div style={{ textAlign: 'center', marginBottom: '20px' }}>
          <h2 style={{ backgroundColor: 'yellow', display: 'inline-block', padding: '5px 20px' }}>POP-UP Resume</h2>
          <h3>Nashville Marriott at Vanderbilt University</h3>
          <div style={{ backgroundColor: '#404040', color: 'white', padding: '5px', marginTop: '10px' }}>
            GROUP COVER SHEET
          </div>
        </div>

        {resume.logo_filename && (
          <div style={{ textAlign: 'center', marginBottom: '20px' }}>
            <img 
              src={`/uploads/group-logos/${resume.logo_filename}`} 
              alt="Group Logo" 
              style={{ maxWidth: '200px', maxHeight: '100px', objectFit: 'contain' }}
            />
          </div>
        )}

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '20px' }}>
          <div><strong>Organization:</strong> {resume.organization}</div>
          <div><strong>Quote #:</strong> {resume.quote_number}</div>
          <div><strong>Post As:</strong> {resume.post_as}</div>
          <div><strong>Departure Date:</strong> {resume.departure_date}</div>
          <div><strong>Arrival Date:</strong> {resume.arrival_date}</div>
        </div>

        <hr />

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '20px' }}>
          <div><strong>Master Account #:</strong> {resume.master_account}</div>
          <div><strong>Market Code:</strong> {resume.market_code}</div>
          <div><strong>Group Contact:</strong> {resume.group_contact}</div>
          <div><strong>Telephone:</strong> {resume.telephone}</div>
          <div><strong>In-House Contact:</strong> {resume.in_house_contact}</div>
          <div><strong>Email:</strong> {resume.email}</div>
          <div><strong>Sales Manager(s):</strong> {resume.sales_manager}</div>
          <div><strong>Event Manager(s):</strong> {resume.event_manager}</div>
          <div><strong>Reservation Coordinator:</strong> {resume.reservation_coordinator}</div>
          <div><strong>General Accountant:</strong> {resume.general_accountant}</div>
        </div>

        {resume.gold_keys && (
          <div style={{ marginBottom: '15px' }}>
            <strong>Gold Keys:</strong>
            <pre style={{ whiteSpace: 'pre-wrap', fontFamily: 'inherit' }}>{resume.gold_keys}</pre>
          </div>
        )}

        <div style={{ marginBottom: '15px' }}>
          <strong>Peak Attendees:</strong> {resume.peak_attendees}
        </div>

        {resume.group_profile && (
          <div style={{ marginBottom: '20px' }}>
            <strong>Group Profile:</strong>
            <p>{resume.group_profile}</p>
          </div>
        )}

        <p style={{ textAlign: 'center', color: '#666', marginTop: '30px' }}>
          Click "Download PDF" to see the full formatted resume
        </p>
      </div>
    </div>
  );
}

export default GroupResumeView;
